import {onlineFeedbackHTML} from './online-feedback.js';
import {ADVANCE,formatLabel} from './deck-format.js';
import {displayTurn} from './turn-count.js';
import {sourceCardCount,sourceCardLabel,sourceCardBadge} from './card-info.js?v=0.722.3';
import {battlePrimaryAction} from './battle-controls.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,disabled=false,extra='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${text}</button>`;
const phase={charge:'マナ',main:'召喚・呪文',attack:'攻撃'};
const actionMatchesCard=(a,uid)=>a.uid===uid||!!a.targetUids?.includes(uid);
const hasDefenseChoice=actions=>actions.some(a=>['noBlock','block','guardman','defendMany'].includes(a.kind));
const inspectionId=c=>c.privateFace?.id||c.id;
const inspectionName=c=>c.privateFace?c.name+'（'+c.privateFace.name+'）':c.name;
export function onlineDialogContent(room,{kind,player,zone},{connected=true}={}){
 const game=room?.game;if(!game||![0,1].includes(room.seat))return null;
 const notice=connected?'':'<p class="small" role="status">通信が切れています。最後に確認した内容です。</p>';
 if(kind==='log')return {title:'オンライン対戦ログ',html:notice+([...(room.events||[])].reverse().map(x=>`<p class="online-history-line"><span class="badge">T${displayTurn(x)}</span> ${esc(room.players?.[x.player]?.name||game.players[x.player]?.name)}：${esc(x.text)}</p>`).join('')||'<p>まだログはありません。</p>')};
 if(![0,1].includes(player))return null;
 const p=game.players[player];if(!p)return null;
 if(kind==='field')return {title:`${p.name}のバトルゾーン`,html:notice+`<div class="online-zone-list">${p.battle.map(c=>button('online-pick-card',`${esc(c.hidden?'裏向きのカード':c.name)}${c.tapped?' · タップ中':''}${c.hidden?'':` · ${esc(c.power??'')} ${c.under?.length?' · 下に '+sourceCardCount(c)+'枚':''}`}`,false,`data-uid="${esc(c.uid)}"`)).join('')||'<p>クリーチャーはまだいません。</p>'}</div>`};
 const labels={mana:'マナ',grave:'墓地',extra:'超次元ゾーン',seals:'封印',abyss:'深淵ゾーン',faceUpShields:'表向きシールド',revealedHand:'確認中の手札'};
 if(kind!=='zone'||!Object.hasOwn(labels,zone))return null;
 if(zone==='revealedHand'&&(player!==1-room.seat||!game.revealedHand))return null;
 const cards=zone==='revealedHand'?game.revealedHand:p[zone]||[];
 return {title:`${p.name}の${labels[zone]}`,html:notice+`<div class="online-zone-list">${cards.map(c=>button(['mana','grave','extra','seals','abyss','revealedHand'].includes(zone)?'online-pick-card':'card-detail',`${esc(c.hidden?'裏向き':c.privateFace?c.name+'（'+c.privateFace.name+'）':c.name)}${c.tapped?' · タップ中':''}`,c.hidden&&zone!=='seals'&&!game.actions?.some(a=>a.uid===c.uid||a.targetUids?.includes(c.uid)),`data-uid="${esc(c.uid)}" data-id="${esc(c.hidden?'':c.id||'')}"`)).join('')||'<p>カードはありません。</p>'}</div>`};
}
function numberChoiceHTML(game,revision,disabled,value,context){
 if(!game.numberChoice)return '';
 const min=game.numberMinimum??0,template=game.actions?.find(a=>a.number!==undefined)||game.actions?.[0];
 return `<section class="online-number-choice" aria-label="数字を宣言"><label class="online-number" for="online-number">数字を入力して宣言<input class="field" id="online-number" inputmode="numeric" value="${esc(value)}" placeholder="${min}以上の整数、または∞" aria-label="宣言する数字"><small>${min}以上の整数、または∞を入力。下の候補ボタンからも選べます。</small></label>${button('online-number-submit','入力した数字を宣言',disabled||!template,`data-index="${template?.id??''}" data-revision="${revision}" ${context}`,true)}</section>`;
}
function attackContext(game,seat){
 const a=game.attack;if(!a)return null;
 const player=game.players.findIndex(p=>p.battle.some(c=>c.uid===a.attacker));
 if(player<0)return null;
 const defender=1-player,source=game.players[player].battle.find(c=>c.uid===a.attacker),target=game.players[defender].battle.find(c=>c.uid===a.target);
 const subject=p=>p===seat?'あなた':'相手',name=c=>c?.hidden?'裏向きのカード':c?.name||'クリーチャー';
 const shields=a.target==='player'&&game.players[defender].shieldCount>0;
 const destination=a.target!=='player'?`${subject(defender)}の「${name(target)}」`:shields?`${subject(defender)}のシールド${Number.isInteger(a.shieldIndex)&&a.shieldIndex>=0?' '+(a.shieldIndex+1):''}`:`${subject(defender)}へダイレクトアタック`;
 return {attacker:a.attacker,target:a.target,defender,shields,shieldIndex:a.shieldIndex,text:`${subject(player)}の「${name(source)}」 → ${destination}`};
}
export function onlinePendingMove(room,pending){
 if(!room||!pending||room.revision!==pending.revision||room.phase!=='playing'||room.game?.actor!==room.seat)return null;
 return room.game.actions?.find(a=>JSON.stringify(a)===JSON.stringify(pending.action))||null;
}
function onlineManaPaymentHTML(payment,actions,revision,disabled,context){
 const select=new Map(actions.filter(a=>a.kind==='selectMana').map(a=>[a.uid,a]));
 const attributes=a=>`data-revision="${esc(revision)}" data-index="${a?.id??''}" ${context}`;
 const cards=payment.cards.map(c=>{
  const label=`<span><strong>${esc(c.name)}</strong><br><small>${esc(c.colors.join(' / ')||'無色')} · ${c.value}マナ${c.fromBattle?' · バトルゾーン':''}</small></span>`;
  return button('online-pay-mana',label,disabled||!select.has(c.uid),
   `${attributes(select.get(c.uid))} aria-pressed="${c.selected}"`,c.selected);
 }).join('');
 const confirm=actions.find(a=>a.kind==='confirmMana'),cancel=actions.find(a=>a.kind==='cancelMana');
 return `<section class="online-mana-payment" aria-label="マナの支払い">
  ${payment.source?`<p>${esc(payment.source)}</p>`:''}
  <div role="status"><strong>選択 ${payment.amount} / 必要 ${payment.cost}マナ</strong>
  ${payment.colors.length?`<p class="small">必要な文明 ${payment.colors.map(c=>`${c.paid?'✓':'○'} ${esc(c.name)}`).join('　')}</p>`:''}</div>
  <div class="online-actions">${cards}</div>
  <div class="row wrap gap12">${button('online-pay-mana','このマナで使う',disabled||!confirm,attributes(confirm),true)}
  ${cancel?button('online-pay-mana','キャンセル',disabled,attributes(cancel)):''}</div>
 </section>`;
}
export function onlinePrimaryAction(room,selected=null,pending=null){
 const g=room?.game;if(!g)return {label:'対戦結果',command:'result',disabled:true};
 const own=g.players[room.seat],actions=g.actions||[],selectedCard=[...own.hand,...(own.battle||[]),...(own.grave||[]),...(own.mana||[]),...(own.extra||[]),...(own.abyss||[])].find(x=>x.uid===selected),moves=actions.filter(a=>actionMatchesCard(a,selected)),review=onlinePendingMove(room,pending);
 if(room.phase==='playing'&&g.actor===room.seat&&g.manaPayment){
  const confirm=actions.find(a=>a.kind==='confirmMana');
  return {label:confirm?'このマナで使う':'支払うマナを選ぶ',command:confirm?'move':'choices',move:confirm??null,disabled:false};
 }
 if(room.phase==='playing'&&g.actor===room.seat&&hasDefenseChoice(actions))return {label:'防御を選ぶ',command:'choices',disabled:false,move:null};
 return battlePrimaryAction({actions,human:g.actor===room.seat,finished:['finished','expired'].includes(room.phase),decision:!!g.decision,phase:g.phase,
  selected:!!selectedCard,selectedMoves:moves,selectedType:selectedCard?.type,attacker:moves.some(a=>a.kind==='attack'),attackChoice:review?.kind==='attack'?review:null,endReview:review?.kind==='endTurn'});
}
export function onlineScreenHTML(state,{user,actionContext='',decks=[],selectedDeckId,code='',selected=null,page=0,art,actionsOpen=false,pending=null,numberValue='',valid=()=>true,history=[],evolutionCard=c=>!!c.evolution}={}){
 const context=`data-context="${esc(actionContext)}"`;
 const room=state.room,game=room?.game,busy=state.busy,disabled=busy||!state.connected;
 const notice=state.error?`<div class="notice" role="alert">${esc(state.error)} ${state.retry?.automatic===false?'<small>自動再接続を停止中</small> ':''}${button('online-refresh','再接続',busy)}</div>`:'';
 if(!user)return `<div class="page-head online-lobby-head"><div><h1>友達と対戦</h1><p>デッキを選んで、ルームで待ち合わせ。</p></div></div><section class="panel online-lobby online-login"><h2>まずはGoogleでログイン</h2><p>それぞれ別のGoogleアカウントで参加します。</p>${button('nav','アカウントを開く',false,'data-view="account"',true)}</section>`;
 if(room&&room.phase==='waiting'&&room.seat===0)return `<div class="page-head"><div><div class="eyebrow">PRIVATE ROOM</div><h1>友達を待っています</h1><p>相手がデッキを選んで参加すると対戦が始まります。</p></div></div>${notice}<section class="panel online-lobby">${room.format===ADVANCE?`<p class="small">${formatLabel(room.format)}</p>`:''}<small>ルームコード</small><div class="online-room-code">${esc(room.code.slice(0,8))} ${esc(room.code.slice(8))}</div><div class="row">${button('online-copy-code','コードをコピー')}${button('online-copy-link','招待リンクをコピー')}</div><p>相手もGoogleでログインし、このコードまたは招待リンクから参加してください。</p><p class="small">待機ルームの有効期限は作成から6時間です。手札と山札の中身は相手に表示されません。</p>${button('online-cancel','ルームを閉じる',disabled,context)}${button('online-refresh',busy?'確認中…':'再接続',busy)}</section>`;
 if(game){
 const seat=room.seat,own=game.players[seat],opp=game.players[1-seat],finished=['finished','expired'].includes(room.phase),mine=game.actor===seat&&!finished,all=game.actions||[],cards=[...(game.revealedHand||[]),...own.hand,...own.battle,...own.mana,...own.grave,...(own.abyss||[]),...(own.extra||[]),...(own.seals||[]),...opp.battle,...opp.mana,...opp.grave,...(opp.abyss||[]),...(opp.extra||[]),...(opp.seals||[])],card=cards.find(x=>x.uid===selected),actions=card?all.filter(a=>actionMatchesCard(a,selected)||cards.some(x=>x.uid===a.uid&&x.sealOf===selected)):all,pages=Math.max(1,Math.ceil(actions.length/8)),current=Math.max(0,Math.min(page,pages-1));
 const payment=mine?game.manaPayment:null;
 const attack=finished?null:attackContext(game,seat);
 const status=finished?room.phase==='expired'?'ルームの有効期限が切れました':game.phase==='rematch'?'再試合':game.draw?'引き分け':game.winner===seat?'あなたの勝利！':'相手の勝利':!state.connected?'再接続してください':busy?'送信・更新中…':mine?'あなたの操作':'相手の操作を待っています';
 const title=finished?'対戦終了':game.decision||(hasDefenseChoice(all)?'防御方法を選ぼう':({charge:'マナに置くカードを選ぼう',main:'召喚・呪文を使おう',attack:'攻撃するクリーチャーを選ぼう'})[game.phase])||'操作を選ぶ';
 const primary=onlinePrimaryAction(room,selected,pending),review=onlinePendingMove(room,pending);
 const inspected=mine?game.inspectedCards||[]:[];
 const inspection=inspected.length?`<div class="stack hand-inspection" aria-label="確認したカード">${inspected.map(c=>`<div class="deck-detail-row">${art?art(c.id):''}<div class="grow"><strong>${esc(c.name)}</strong><small>${esc(c.label)}</small></div>${button('card-detail','詳細',false,`data-id="${esc(c.id)}"`)}</div>`).join('')}</div>`:'';
 const primaryButton=button('online-primary',esc(primary.label),(disabled&&!finished)||primary.disabled,`data-revision="${room.revision}" ${context} aria-controls="online-controls"`,true);
 const reviewHTML=review?`<div class="online-move-review"><strong>${review.kind==='endTurn'?'まだ攻撃できるクリーチャーがいます':'攻撃内容を確認'}</strong><p>${esc(review.kind==='endTurn'?'攻撃せずにターンを終了しますか？':review.label)}</p><div class="row">${button('online-cancel-move','選び直す')}${button('online-confirm-move',review.kind==='endTurn'?'ターン終了':'攻撃する',disabled,`data-revision="${room.revision}" data-index="${review.id}" ${context}`,true)}</div></div>`:'';
 const board=(p,who)=>{
  const mine=who===seat;
  const shields=`<div class="play-shields ${attack?.shields&&attack.defender===who?'is-under-attack':''}"><span class="zone-caption">◇ <b>${p.shieldCount}</b></span><div class="shield-tiles" data-fit-grid="shields" data-fit-count="${p.shieldCount}" data-fit-layout="rail" style="--fit-cols:${Math.max(1,Math.min(5,p.shieldCount))};--fit-rows:${Math.max(1,Math.ceil(p.shieldCount/5))}">${Array.from({length:p.shieldCount},(_,i)=>`<span class="shield-tile${attack?.shields&&attack.defender===who&&(attack.shieldIndex===i||attack.shieldIndex==null)?' is-attack-target':''}" aria-label="${mine?'自分':'相手'}のシールド${i+1}${p.shieldGroups?.[i]?.cardCount>1?'・'+p.shieldGroups[i].cardCount+'枚の束':''}">${i+1}${p.shieldGroups?.[i]?.cardCount>1?`<small class="shield-card-count">${p.shieldGroups[i].cardCount}枚</small>`:''}</span>`).join('')||'<span class="no-shields">シールドなし</span>'}</div>${p.faceUpShields?.length?button('online-zone','表向き',false,`data-player="${who}" data-zone="faceUpShields"`):''}</div>`;
  const attachmentHolder=ref=>ref&&p.battle.find(x=>x.uid===ref.uid&&!x.hidden);
  const field=`<div class="play-creatures online-field" data-fit-grid="creatures" data-fit-count="${p.battle.length}" style="--fit-cols:${Math.max(1,Math.min(5,p.battle.length))};--fit-rows:${Math.max(1,Math.ceil(p.battle.length/5))}" aria-label="${mine?'自分':'相手'}のバトルゾーン">${p.battle.map((c,i)=>`<article class="play-creature ${attack?.attacker===c.uid?'is-attacking':''} ${attack?.target===c.uid?'is-attack-target':''} ${c.sealed?'is-sealed':''} ${c.tapped?'is-tapped':''} ${selected===c.uid?'is-selected':''} ${all.some(a=>a.uid===c.uid)?'is-ready':''}"><button class="creature-tap" data-action="online-card" data-uid="${esc(c.uid)}" aria-label="${esc(c.hidden?'裏向きのカード':c.name)}を選ぶ${attack?.attacker===c.uid?'・攻撃中':attack?.target===c.uid?'・攻撃対象':''}${!c.hidden&&!c.sealed&&c.type==='creature'&&sourceCardLabel(c,evolutionCard(c))?'・'+sourceCardLabel(c,evolutionCard(c)):''}" aria-pressed="${selected===c.uid}">${!c.hidden&&art?art(c.id,{awakened:!!c.awakened}):''}${c.type==='creature'?sourceCardBadge(c,evolutionCard(c)):''}<span class="compact-creature-index">${i+1}</span><span class="compact-creature-name">${esc(c.hidden?'裏向き':c.name)}</span><span class="compact-creature-state">${c.sealed?'封印中':c.tapped?'タップ中':all.some(a=>a.uid===c.uid&&a.kind==='attack')?'攻撃可':''}</span><span class="creature-current-power">${c.sealed?'封印 '+c.sealCount+'枚':c.hidden?'?':c.type==='gear'?'クロスギア':c.type==='aura'?(attachmentHolder(c.auraTo)?'装着：'+esc(attachmentHolder(c.auraTo).name):'オーラ'):c.type==='weapon'?(attachmentHolder(c.weaponTo)?'装備：'+esc(attachmentHolder(c.weaponTo).name):'ウエポン'):c.type==='seed'?'タマシード':c.type==='field'?'下 '+sourceCardCount(c)+'枚'+(c.worldUsed?' · 使用済':''):esc(c.power||0)}</span></button></article>`).join('')||'<div class="play-empty">クリーチャーはまだいません</div>'}</div>`;
  return `<section class="online-player ${mine?'own-field':'opponent-field'}"><div class="play-player ${attack?.target==='player'&&!attack.shields&&attack.defender===who?'is-attack-target':''}"><span class="player-avatar ${mine?'mine':''}">${mine?'YOU':'VS'}</span><strong>${esc(p.name)}</strong><small>${who===game.first?'先攻':'後攻'}</small>${p.grCount!==undefined||p.extra?.length||p.seals?.length||p.abyss?.length?`<div class="play-special-zones">${p.grCount!==undefined?`<span>超GR ${p.grCount}枚</span>`:''}${p.extra?.length?button('online-zone','超次元 '+p.extra.length,false,`data-player="${who}" data-zone="extra"`):''}${p.seals?.length?button('online-zone','封印 '+p.seals.length,false,`data-player="${who}" data-zone="seals"`):''}${p.abyss?.length?button('online-zone','深淵 '+p.abyss.length,false,`data-player="${who}" data-zone="abyss"`):''}</div>`:''}<button class="field-overview-button" data-action="online-field" data-player="${who}" aria-label="${mine?'自分':'相手'}の場を拡大して見る">場 ${p.battle.length} ↗</button></div><div class="play-resources"><span><b>${p.deckCount}</b> 山札${p.sidewaysPositions?.length?`<small class="sideways-position" title="横向きのカード：上から${p.sidewaysPositions.join("・")}枚目">横${p.sidewaysPositions[0]}枚目${p.sidewaysPositions.length>1?"ほか":""}</small>`:""}</span>${!mine&&game.revealedHand?button('online-zone','相手の手札を見る '+game.revealedHand.length,false,`data-player="${who}" data-zone="revealedHand"`):`<span><b>${p.handCount}</b> 手札${mine?'':'・非公開'}</span>`}<button data-action="online-zone" data-player="${who}" data-zone="mana"><b>${p.mana.length}</b> マナ ›</button><button data-action="online-zone" data-player="${who}" data-zone="grave"><b>${p.grave.length}</b> 墓地 ›</button></div>${mine?field+shields:shields+field}</section>`;
 };
 const hand=own.hand.map(c=>`<button class="hand-shelf-card ${all.some(a=>a.uid===c.uid)?'can-use':''} ${selected===c.uid?'is-selected':''}" data-action="online-card" data-uid="${esc(c.uid)}" aria-pressed="${selected===c.uid}" aria-label="${esc(c.name)}を拡大"><span class="hand-shelf-art">${art?art(c.id):''}</span><span class="hand-shelf-cost">${esc(c.cost)}</span>${all.some(a=>a.uid===c.uid)?`<span class="hand-shelf-ready">${game.phase==='charge'?'マナ':'操作可'}</span>`:''}<strong>${esc(c.name)}</strong></button>`).join('');
 return `<div class="online-match"><header class="online-match-head"><div class="manual-heading"><span class="live-duel-dot"></span><strong>友達と対戦</strong><span class="manual-turn">TURN ${displayTurn(game)}</span></div><div>${button('online-refresh','再接続',busy)}${button('online-menu','<span aria-hidden="true">⋯</span>',false,'aria-label="対戦メニュー"')}</div></header>${notice}<div class="manual-turnbar online-turnbar ${mine?'':'is-opponent'}"><strong class="online-connection" role="status">${esc(status)}</strong><ol class="manual-phase">${Object.entries(phase).map(([key,label],i)=>`<li class="${game.phase===key?'is-current':''}" ${game.phase===key?'aria-current="step"':''}><b>${i+1}</b>${label}</li>`).join('')}</ol></div>${onlineFeedbackHTML(state.feedback,seat)}${attack?`<div class="online-attack-status" role="status" aria-label="進行中の攻撃"><strong>攻撃中</strong><span>${esc(attack.text)}</span></div>`:''}<div class="online-stage"><div class="online-board play-board" role="region" aria-label="対戦の盤面全体">${board(opp,1-seat)}<div class="board-divider"><span>DUEL MASTERS</span><b>VS</b><span>DECK LAB</span></div>${board(own,seat)}</div><section class="online-hand hand-shelf" aria-label="自分の手札"><div class="hand-shelf-head"><strong>手札 <b>${own.handCount}</b></strong><small>左右にスワイプ・タップで拡大</small>${own.deckTop?button('card-detail','山札の上：'+esc(own.deckTop.name),false,`data-id="${esc(own.deckTop.id)}"`):''}</div><div class="online-hand-track hand-shelf-cards">${hand||'<p class="hand-shelf-empty">手札がありません</p>'}</div></section><div class="online-dock"><div>${review?button('online-cancel-move','選び直す'):selected?button('online-clear-selection','選択を解除'):''}${primaryButton}</div></div>${actionsOpen?`<section class="online-controls" id="online-controls" role="region" aria-label="対戦の操作"><div class="online-controls-head"><h2>${esc(payment?title:card?card.hidden?'裏向きのカード':inspectionName(card):title)}</h2>${button('online-actions-close','盤面に戻る',false,'aria-label="操作パネルを閉じて盤面に戻る"')}</div><div class="online-action-drawer">${payment?onlineManaPaymentHTML(payment,all,room.revision,disabled,context):`${card?`<div class="online-card-detail">${!card.hidden&&art?art(inspectionId(card)):''}<div><strong>${esc(card.hidden?'裏向きのカード':inspectionName(card))}</strong><p>コスト ${esc(card.cost??'?')}${card.tapped?' · タップ中':''}${!card.hidden&&!card.sealed&&sourceCardLabel(card,evolutionCard(card))?' · '+sourceCardLabel(card,evolutionCard(card)):''}</p>${!card.hidden?button('card-detail',card.privateFace?'元のカードを見る':'能力を見る',false,`data-id="${esc(inspectionId(card))}"`):''}</div></div>`:''}${inspection}${numberChoiceHTML(game,room.revision,disabled||!mine,numberValue,context)}${reviewHTML}${!review?`<div class="online-actions">${actions.slice(current*8,current*8+8).map(a=>button('online-move',esc(a.label),disabled||!mine,`data-index="${a.id}" data-revision="${room.revision}" ${context}`,true)).join('')}</div>`:''}${!review&&!actions.length&&!finished?`<p class="small">${mine?card?'このカードで選べる操作はありません。':'選べる操作はありません。':esc(status)}</p>`:''}${pages>1?`<div class="online-paging">${button('online-page','前へ',current===0,`data-page="${current-1}"`)}<span>${current+1} / ${pages}</span>${button('online-page','次へ',current===pages-1,`data-page="${current+1}"`)}</div>`:''}${card?button('online-all-actions',game.decision?'効果の選択に戻る':'全操作を表示'):''}${finished?`<p>${esc(status)} · ${esc(game.reason)}</p>${game.phase==='rematch'?'<p>再試合は同じデッキで新しいルームを作成してください。</p>':''}${button('online-back','ルーム画面へ')}`:''}`}</div></section>`:''}</div></div>`;
 }

 const choices=decks.map(d=>`<option value="${esc(d.id)}" ${d.id===selectedDeckId?'selected':''} ${!valid(d)?'disabled':''}>${esc(d.name)}${d.format===ADVANCE?' · '+formatLabel(d.format):''}${!valid(d)?'（対戦未対応）':''}</option>`).join(''),hasDeck=decks.some(valid);
 const createRoom=`<section class="panel online-lobby online-room-option" aria-labelledby="online-create-title"><h3 id="online-create-title">ルームを作る</h3><p>コードを友達に送って招待します。</p>${button('online-create',busy?'確認中…':'ルームを作る',busy||!hasDeck,context,true)}</section>`;
 const joinRoom=`<section class="panel online-lobby online-room-option" aria-labelledby="online-join-title"><h3 id="online-join-title">${code?'招待されたルームに参加':'コードで参加する'}</h3><label for="online-code">友達から届いたルームコード</label><input class="field" id="online-code" value="${esc(code)}" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="40" placeholder="コードを入力・貼り付け" aria-label="ルームコード">${button('online-join',busy?'確認中…':'このデッキで参加',busy||!hasDeck,context,true)}</section>`;
 return `<div class="page-head online-lobby-head"><div><h1>友達と対戦</h1><p>デッキを選んで、ルームで待ち合わせ。</p></div><span class="badge green online-account">${esc(user.name||'Googleアカウント')} でログイン中</span></div>${notice}<section class="panel online-lobby online-deck-setup" aria-labelledby="online-deck-title"><h2 class="online-step-heading" id="online-deck-title"><span aria-hidden="true">1</span>使うデッキを選ぶ</h2><label for="online-deck">マイデッキ</label><select class="field" id="online-deck" aria-label="オンライン対戦に使うデッキ">${choices||'<option>デッキがありません</option>'}</select>${!hasDeck?`<p class="online-deck-warning" role="status">40枚すべての効果に対応したデッキが必要です。</p>${button('nav','マイデッキへ',false,'data-view="decks"')}`:'<p class="small">ルーム作成・参加のどちらにも、このデッキを使います。</p>'}</section><section class="online-start" aria-labelledby="online-start-title"><h2 class="online-step-heading" id="online-start-title"><span aria-hidden="true">2</span>対戦の始め方を選ぶ</h2><div class="online-lobby-grid">${code?joinRoom+createRoom:createRoom+joinRoom}</div></section>${room&&['expired','cancelled','finished'].includes(room.phase)?'<p class="notice">前のルームは終了しています。新しく作成できます。</p>':''}<section class="online-lobby-tools" aria-label="対戦の再開とヘルプ">${button('online-resume','中断した対戦を探す',busy)}<details class="online-help"><summary>友達対戦の使い方</summary><ul><li>それぞれ別のGoogleアカウントでログインします。</li><li>どちらかがルームを作り、コードか招待リンクを送ります。</li><li>もう一人がデッキを選んで参加すると、対戦が始まります。</li><li>対戦には開始時の構成を使います。元のデッキを編集しても盤面には影響しません。</li></ul></details></section>${history.length?`<section class="panel online-lobby online-recent"><h2>最近の対戦</h2><ul>${history.slice(0,10).map(h=>`<li><strong>${esc(h.result)}</strong><span>${esc(h.opponent)}</span><small>${displayTurn(h)}ターン</small></li>`).join('')}</ul></section>`:''}`;
}
